-- R6 Legacy and Compatibility Removal.
-- Retires removed browser administration routes and republishes the current canonical TARGET_ONLY inventory.

select set_config('app.current_tenant_id','INSTANCE',true);
select set_config('app.current_actor_id','r6-legacy-compatibility-removal',true);

update permission_entry_point_inventory set authority_state='EXEMPT',target_permission_code=null,legacy_authority_type=null,legacy_authorities='[]'::jsonb,resource_resolver_id='NONE',exemption_reason='Endpoint removed by R6 canonical administration cutover',migration_deadline=null,updated_at=now(),updated_by='r6-legacy-compatibility-removal',version=version+1 where entry_point_type='REST' and (route_pattern like '/api/identity/%' or route_pattern like '/api/security/%' or route_pattern like '/api/auth/%' or route_pattern like '/api/legacy-auth/%' or route_pattern like '/api/iam-migration/%' or route_pattern like '/api/platform/users%' or route_pattern like '/api/platform/roles%' or route_pattern like '/api/platform/permissions%');

