on conflict(entry_point_id) do update set
 entry_point_type=excluded.entry_point_type,application_id=excluded.application_id,owner_module=excluded.owner_module,
 display_name=excluded.display_name,route_pattern=excluded.route_pattern,http_method=excluded.http_method,
 authority_state='TARGET_ONLY',target_permission_code=excluded.target_permission_code,legacy_authority_type=null,
 legacy_authorities='[]'::jsonb,resource_type=excluded.resource_type,resource_resolver_id=excluded.resource_resolver_id,
 exemption_reason=null,migration_deadline=null,manifest_revision=excluded.manifest_revision,source_ref=excluded.source_ref,
 source_hash=excluded.source_hash,last_verified_at=now(),updated_at=now(),updated_by='r6-legacy-compatibility-removal',
 version=permission_entry_point_inventory.version+1;

do $$
declare v_target integer; v_access integer;
begin
 select count(*) into v_target from permission_entry_point_inventory where manifest_revision='r6-legacy-compatibility-removal-2026-08-04' and authority_state='TARGET_ONLY';
 if v_target <> 684 then raise exception 'R6 TARGET_ONLY inventory incomplete: expected 684, found %',v_target; end if;
 select count(*) into v_access from permission_entry_point_inventory where manifest_revision='r6-legacy-compatibility-removal-2026-08-04' and route_pattern like '/api/admin/access/%' and authority_state='TARGET_ONLY';
 if v_access <> 133 then raise exception 'R6 Access Management inventory incomplete: expected 133, found %',v_access; end if;
 if exists(select 1 from permission_entry_point_inventory where manifest_revision='r6-legacy-compatibility-removal-2026-08-04' and (target_permission_code is null or resource_resolver_id is null or authority_state<>'TARGET_ONLY')) then raise exception 'R6 canonical route has incomplete authorization metadata'; end if;
 if exists(select 1 from permission_entry_point_inventory where manifest_revision='r6-legacy-compatibility-removal-2026-08-04' and (route_pattern like '/api/identity/%' or route_pattern like '/api/security/%' or route_pattern like '/api/auth/%' or route_pattern like '/api/legacy-auth/%' or route_pattern like '/api/iam-migration/%')) then raise exception 'R6 inventory still contains retired browser administration routes'; end if;
end $$;

update permission_legacy_authority_mappings set status='RETIRED',updated_at=now(),updated_by='r6-legacy-compatibility-removal',version=version+1 where status<>'RETIRED';

-- permission_entry_point_bypasses is an append/revoke lifecycle table created by V90.
-- It intentionally has no updated_at or updated_by columns; revocation provenance belongs
-- in revoked_at, revoked_by and revoke_reason. Keep the update compatible with the
-- FORCE-RLS instance-scoped contract established by V91.
update permission_entry_point_bypasses
   set status='REVOKED',
       revoked_at=coalesce(revoked_at,now()),
       revoked_by=coalesce(revoked_by,'r6-legacy-compatibility-removal'),
       revoke_reason=coalesce(
         nullif(trim(revoke_reason),''),
         'R6 canonical administration cutover removed the API bypass'
       ),
       version=version+1
 where status='ACTIVE'
   and entry_point_id like 'REST:%:/api/%';

update rbac_policy_versions set policy_version=policy_version+1,updated_at=now(),updated_by='r6-legacy-compatibility-removal';
insert into rbac_policy_versions(scope_type,scope_id,tenant_id,policy_version,updated_at,updated_by) select 'TENANT',tenant_id,tenant_id,1,now(),'r6-legacy-compatibility-removal' from tenants on conflict(scope_type,scope_id) do update set policy_version=rbac_policy_versions.policy_version+1,updated_at=now(),updated_by='r6-legacy-compatibility-removal';
